property int commitFrame: -1
property int commitModel: -1
property int commitAxis: -1

// 007 U6 (U5-verified): Qt 6.7 ListView pooling does NOT drop focus
// (hidden/reparented items keep activeFocus), so the "focus loss fires
// editingFinished before pooling" contract never fires on recycle —
// the typed value would be silently clobbered by resetDisplay without
// a commit. Track interactive edits and commit them explicitly from
// the delegate's onPooled (commit-on-pool, made real).
property bool edited: false

onActiveFocusChanged: {
