// editing; this flag survives focus transitions).
onTextEdited: edited = true

onEditingFinished: doCommit()

// The single commit path: captured tuple + live text. A rejected
// commit re-arms the storedValue binding (C1).
function doCommit() {
    if (!edited) return
    edited = false
